    h, w = len(grid), len(grid[0])
    # Try row, column, and both diagonal stripe orientations. A valid
    # orientation has no stripe containing more than one non-background color.
    keys = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: r - c,
    ]
    for key in keys:
        groups = {}
        for r in range(h):
            for c in range(w):
                groups.setdefault(key(r, c), set())
                if grid[r][c] != 0:
                    groups[key(r, c)].add(grid[r][c])
        if any(len(colors) > 1 for colors in groups.values()):
            continue
        anchors = {k: next(iter(v)) for k, v in groups.items() if v}
        if len(anchors) < 2:
            continue
        period = len(anchors)
        motif = {k % period: color for k, color in anchors.items()}
        if len(motif) != len(anchors):
            continue
        return [[motif[key(r, c) % period] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]

